import numpy as np, itertools
lines=open('opt1.xyz').read().split('\n')[2:]
coords=[]
for l in lines:
    p=l.split()
    if len(p)==4: coords.append((p[0],np.array(list(map(float,p[1:4])))))
n=len(coords)
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'Cl':1.02,'Rh':1.42}
bonds=[]
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(coords[i][1]-coords[j][1])
    if d < cov[coords[i][0]]+cov[coords[j][0]]+0.45:
        bonds.append((i,j,round(d,2)))
# print bonds involving key atoms
